from taf.transport.ssh import ssh

csn = ssh()

__all__ = ['feature_1514_opened']


def feature_1514_opened(connection):
    """Author: jingmin.he@nokia-sbell.com
    Description: Check if feature 1514 is used in current package
    :param connection: session alias of ssh connection
    :return: if True, feature 1514 available, else not available"""
    cmd = 'cat /ffs/run/boardcfg/0/A/mcu-*/config/bpd-ipv6.txt'
    ssh_session = csn.get_connection_by_alias(connection)
    res = ssh_session.execute(cmd)
    if res.splitlines()[0] == '1':
        return True
    return False
